--[=[
    @class IHostBuilder
    主机构建器接口
]=]

export type IHostBuilder = {
	Services: IServiceCollection,

	-- 配置主机配置
	ConfigureHostConfiguration: (
		self: IHostBuilder,
		configureDelegate: (configurationBuilder: IConfigurationBuilder) -> ()
	) -> IHostBuilder,

	-- 配置应用程序配置
	ConfigureAppConfiguration: (
		self: IHostBuilder,
		handler: (
			hostBuilderContext: IHostBuilderContext,
			configurationBuilder: IConfigurationBuilder
		) -> ()
	) -> IHostBuilder,

	--- 配置环境变量
	ConfigureHostingEnvironment: (
		self: IHostBuilder,
		handler: (hostingEnvironment: IHostingEnvironment) -> ()
	) -> IHostBuilder,

	-- 配置服务
	ConfigureServices: (
		self: IHostBuilder,
		handler: (
			hostBuilderContext: IHostBuilderContext,
			services: IServiceCollection
		) -> ()
	) -> IHostBuilder,

	-- 构建主机
	Build: (self: IHostBuilder) -> IHost
}

return {}
